mapper.select:
SELECT tenant_id FROM tc_job_lease FORCE INDEX (idx_job_tenant_rotation)
WHERE job_type=#{type} AND runnable=1 AND tenant_id>#{after}
ORDER BY tenant_id LIMIT 1

mapper.update:
UPDATE tc_job_lease SET lease_until=GREATEST(lease_until,TIMESTAMPADD(MICROSECOND,#{leaseMicros},UTC_TIMESTAMP(3))),
  next_run_at=lease_until,updated_at=UTC_TIMESTAMP(3),version=version+1
WHERE tenant_id=#{tenant} AND id=#{id} AND status='RUNNING' AND owner=#{owner}
  AND fencing_token=#{token} AND lease_until > UTC_TIMESTAMP(3)
  AND job_type=#{type} AND business_key=#{business}
